    Multi-start greedy placement: several model orderings (pressure desc,
    size desc, pressure-density desc, req_rate desc) are each greedily
    placed (each model onto the GPU yielding the lowest resulting KVPR);
    infeasible orderings fall back to first-fit so placement never fails.
    Each result is refined by a local search that moves or swaps models
    off the worst-KVPR GPU whenever it lowers the max KVPR, and the best
    placement across all starts is returned.
    """
    def p(m):
        return m.req_rate / m.slo

    starts = [
        sorted(models, key=p, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: p(m) / m.model_size, reverse=True),
        sorted(models, key=lambda m: m.req_rate, reverse=True),
    ]

    def greedy(order):
        placement = {gpu_id: [] for gpu_id in range(gpu_num)}
        shared_kv = [GPU_MEM_SIZE for _ in range(gpu_num)]
        weighted_req_rate = [0.0 for _ in range(gpu_num)]
        for model in order:
            best_idx, best_ratio = None, float('inf')
            for gpu_id in range(gpu_num):
                remaining = shared_kv[gpu_id] - model.model_size
                if remaining > 0:
                    new_ratio = (weighted_req_rate[gpu_id] + p(model)) / remaining
                    if new_ratio < best_ratio:
                        best_ratio, best_idx = new_ratio, gpu_id
            if best_idx is None:
                # fallback: first-fit by memory only
                for gpu_id in range(gpu_num):
                    if shared_kv[gpu_id] - model.model_size > 0:
                        best_idx = gpu_id
                        break
            if best_idx is None:
                return None
            placement[best_idx].append(model)
            weighted_req_rate[best_idx] += p(model)
            shared_kv[best_idx] -= model.model_size
        return placement, shared_kv, weighted_req_rate

    def kvpr(g):
        if shared_kv[g] <= 0:
            return 0.0 if weighted_req_rate[g] == 0.0 else float('inf')
        return weighted_req_rate[g] / shared_kv[g]

    def cur_max():
        return max(kvpr(g) for g in range(gpu_num))

    def local_search(placement, shared_kv, weighted_req_rate):
        for _ in range(2 * len(models) + 4):
            worst = max(range(gpu_num), key=kvpr)
            if not placement[worst] or kvpr(worst) == 0.0:
                break
            target, improved = cur_max(), False

            # Move phase: relocate a model off the worst GPU
            for model in sorted(placement[worst], key=p, reverse=True):
                for gpu_id in range(gpu_num):
                    if gpu_id == worst or shared_kv[gpu_id] - model.model_size <= 0:
                        continue
                    weighted_req_rate[worst] -= p(model)
                    shared_kv[worst] += model.model_size
                    weighted_req_rate[gpu_id] += p(model)
                    shared_kv[gpu_id] -= model.model_size
                    if cur_max() < target:
                        placement[worst].remove(model)
                        placement[gpu_id].append(model)
                        improved = True
                        break
                    weighted_req_rate[worst] += p(model)
                    shared_kv[worst] -= model.model_size
                    weighted_req_rate[gpu_id] -= p(model)
                    shared_kv[gpu_id] += model.model_size
                if improved:
                    break
            if improved:
                continue

            # Swap phase: exchange a model on the worst GPU with one elsewhere
            for m1 in sorted(placement[worst], key=p, reverse=True):
                for gpu_id in range(gpu_num):
                    if gpu_id == worst:
